package io.github.diodeme.ji.acp.v1;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.agentclientprotocol.sdk.spec.AcpSchema;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.github.diodeme.ji.agent.AgentRuntimeBuilder;
import io.github.diodeme.ji.agent.ToolDefinition;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.ModelStreamEvent;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.host.MemoryHostStore;
import io.github.diodeme.ji.host.PermissionBroker;
import io.github.diodeme.ji.host.PromptApplicationService;
import io.github.diodeme.ji.host.SessionApplicationService;
import io.github.diodeme.ji.testkit.ScriptedModelProvider;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PipedInputStream;
import java.io.PipedOutputStream;
import java.io.PrintWriter;
import java.nio.charset.StandardCharsets;
import java.time.Clock;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;

@Timeout(value = 15, unit = TimeUnit.SECONDS)
class AcpV1ServerTest {
    private static final ObjectMapper MAPPER = new ObjectMapper();

    @Test
    void fixedClientDrivesNewLoadPromptToolPermissionAndCanonicalTranscript() throws Exception {
        var provider = new ScriptedModelProvider()
                .enqueue(List.of(new ScriptedModelProvider.Step.Text("Work"),
                        new ScriptedModelProvider.Step.Text("ing"),
                        new ScriptedModelProvider.Step.Tool("call-1", "echo", Map.of("value", "hello")),
                        new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.TOOL_USE)))
                .enqueue(List.of(new ScriptedModelProvider.Step.Text("Done"),
                        new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        PermissionBroker permissions = new PermissionBroker(Clock.systemUTC());
        var hostStore = new MemoryHostStore();
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(hostStore)
                .permissionDecider(permissions)
                .tool(ToolDefinition.sync("echo", "Echo input", Map.of("type", "object"),
                        (arguments, cancellation) -> ToolDefinition.ToolResult.text("echoed " + arguments.get("value"))))
                .build();
             var sessions = new SessionApplicationService(runtime);
             var harness = new StdioHarness(sessions, permissions,
                     new PromptApplicationService(sessions, hostStore))) {
            harness.request(1, "initialize", Map.of("protocolVersion", 1, "clientCapabilities", Map.of()));
            JsonNode created = harness.request(2, "session/new", Map.of("cwd", ".", "mcpServers", List.of()));
            String sessionId = created.path("result").path("sessionId").asText();
            assertTrue(!sessionId.isBlank());
            harness.request(3, "session/load", Map.of("sessionId", sessionId, "cwd", ".", "mcpServers", List.of()));

            JsonNode terminal = harness.prompt(4, sessionId, "echo hello", "command-1");
            assertEquals("end_turn", terminal.path("result").path("stopReason").asText());
            assertEquals(List.of("Work", "ing", "Done"), harness.agentChunks());
            assertTrue(harness.toolStatuses().contains("pending"));
            assertTrue(harness.toolStatuses().contains("completed"));
            assertEquals(List.of("echo hello", "Working", "echoed hello", "Done"),
                    sessions.transcript(sessionId).stream().map(message -> message.text()).toList());
            assertEquals(2, provider.capturedRequests().size());
        }
    }

    @Test
    void fixedClientCancelsActivePrompt() throws Exception {
        var gate = new ScriptedModelProvider.Gate();
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Start("response-1"),
                new ScriptedModelProvider.Step.Wait(gate),
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        PermissionBroker permissions = new PermissionBroker(Clock.systemUTC());
        var hostStore = new MemoryHostStore();
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(hostStore)
                .permissionDecider(permissions).build();
             var sessions = new SessionApplicationService(runtime);
             var harness = new StdioHarness(sessions, permissions,
                     new PromptApplicationService(sessions, hostStore))) {
            harness.request(1, "initialize", Map.of("protocolVersion", 1, "clientCapabilities", Map.of()));
            String sessionId = harness.request(2, "session/new", Map.of("cwd", ".", "mcpServers", List.of()))
                    .path("result").path("sessionId").asText();
            harness.sendRequest(3, "session/prompt", Map.of("sessionId", sessionId,
                    "prompt", List.of(Map.of("type", "text", "text", "wait")),
                    "_meta", Map.of("commandId", "command-cancel")));
            long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
            while (!sessions.hasActiveRun(sessionId) && System.nanoTime() < deadline) Thread.onSpinWait();
            assertTrue(sessions.hasActiveRun(sessionId), "prompt did not start");
            harness.notify("session/cancel", Map.of("sessionId", sessionId));
            JsonNode terminal = harness.readResponse(3);
            assertEquals("cancelled", terminal.path("result").path("stopReason").asText());
            assertEquals(List.of("wait"), sessions.transcript(sessionId).stream().map(message -> message.text()).toList());
        }
    }

    private static final class StdioHarness implements AutoCloseable {
        private final SessionApplicationService sessions;
        private final PipedInputStream serverInput = new PipedInputStream();
        private final PipedOutputStream serverOutput = new PipedOutputStream();
        private final PipedInputStream clientInput;
        private final PipedOutputStream clientOutput;
        private final BufferedReader reader;
        private final PrintWriter writer;
        private final AcpV1Server server;
        private final Thread thread;
        private final List<String> agentChunks = new ArrayList<>();
        private final List<String> toolStatuses = new ArrayList<>();

        StdioHarness(SessionApplicationService sessions, PermissionBroker permissions,
                     PromptApplicationService prompts) throws Exception {
            this.sessions = sessions;
            clientInput = new PipedInputStream(serverOutput);
            clientOutput = new PipedOutputStream(serverInput);
            reader = new BufferedReader(new InputStreamReader(clientInput, StandardCharsets.UTF_8));
            writer = new PrintWriter(clientOutput, true, StandardCharsets.UTF_8);
            server = new AcpV1Server(serverInput, serverOutput, sessions, permissions, prompts,
                    new ModelRef("faux", "faux-1"));
            thread = Thread.startVirtualThread(server::run);
        }

        JsonNode request(long id, String method, Object params) throws Exception {
            sendRequest(id, method, params);
            return readResponse(id);
        }

        JsonNode prompt(long id, String sessionId, String text, String commandId) throws Exception {
            sendRequest(id, "session/prompt", Map.of("sessionId", sessionId,
                    "prompt", List.of(Map.of("type", "text", "text", text)),
                    "_meta", Map.of("commandId", commandId)));
            return readResponse(id);
        }

        synchronized void sendRequest(long id, String method, Object params) throws Exception {
            writer.println(MAPPER.writeValueAsString(Map.of(
                    "jsonrpc", "2.0", "id", id, "method", method, "params", params)));
        }

        synchronized void notify(String method, Object params) throws Exception {
            writer.println(MAPPER.writeValueAsString(Map.of(
                    "jsonrpc", "2.0", "method", method, "params", params)));
        }

        JsonNode readResponse(long id) throws Exception {
            return readResponseBlocking(id);
        }

        private JsonNode readResponseBlocking(long id) throws IOException {
            while (true) {
                String line = reader.readLine();
                if (line == null) throw new AssertionError("ACP stream closed before response " + id);
                JsonNode message = MAPPER.readTree(line);
                if (message.has("id") && message.path("id").asLong() == id) return message;
                if ("session/update".equals(message.path("method").asText())) recordUpdate(message);
                else if ("session/request_permission".equals(message.path("method").asText())) {
                    sendPermission(message.path("id"));
                }
            }
        }

        private synchronized void sendPermission(JsonNode id) throws IOException {
            var response = MAPPER.createObjectNode();
            response.put("jsonrpc", "2.0");
            response.set("id", id);
            response.set("result", MAPPER.valueToTree(
                    Map.of("outcome", Map.of("outcome", "selected", "optionId", "allow"))));
            writer.println(MAPPER.writeValueAsString(response));
        }

        private void recordUpdate(JsonNode message) {
            JsonNode update = message.path("params").path("update");
            String kind = update.path("sessionUpdate").asText();
            if ("agent_message_chunk".equals(kind)) agentChunks.add(update.path("content").path("text").asText());
            if ("tool_call".equals(kind) || "tool_call_update".equals(kind)) {
                toolStatuses.add(update.path("status").asText());
            }
        }

        List<String> agentChunks() {
            return List.copyOf(agentChunks);
        }

        List<String> toolStatuses() {
            return List.copyOf(toolStatuses);
        }

        @Override
        public void close() {
            try {
                clientOutput.close();
                thread.join(TimeUnit.SECONDS.toMillis(5));
                if (thread.isAlive()) throw new AssertionError("ACP server did not stop");
                server.close();
                reader.close();
                clientInput.close();
                serverOutput.close();
                serverInput.close();
            } catch (java.io.IOException exception) {
                throw new java.io.UncheckedIOException(exception);
            } catch (InterruptedException exception) {
                Thread.currentThread().interrupt();
                throw new IllegalStateException("interrupted while closing ACP harness", exception);
            }
        }
    }
}

